from lib import *
S = SS('x30')
steps = [
    step("外面有事务、里面也成功。REQUIRED、NESTED、SUPPORTS、MANDATORY 都加入外层事务:inner 事务活跃,连接 id 和外层相同(12),提交后行是 outer+inner。REQUIRES_NEW 另开一个新事务,用另一个连接(13),也提交了两行。NOT_SUPPORTED 把外层事务挂起,inner 在没有事务的状态下跑(事务活跃=false),用另一个连接(13)。NEVER 在已经有事务时直接抛 IllegalTransactionStateException:Existing transaction found for transaction marked with propagation 'never'。", t=tl(S(1)), mark=lidx(S(1), 'REQUIRES_NEW   外有事务、都成功', 'NOT_SUPPORTED  外有事务、都成功', 'NEVER          外有事务、都成功'), done=lidx(S(1), 'REQUIRED       外有事务、都成功', 'NESTED         外有事务、都成功', 'SUPPORTS       外有事务、都成功', 'MANDATORY      外有事务、都成功'), b=bars([['加入外层事务(同一连接 12)的传播行为个数', 4, '4:REQUIRED、NESTED、SUPPORTS、MANDATORY'], ['用另一个连接(13)的个数', 2, '2:REQUIRES_NEW、NOT_SUPPORTED'], ['直接抛异常的个数', 1, '1:NEVER']], 4, done=[0], cur=[1], mark=[2]), kv=KV([['REQUIRED / NESTED / SUPPORTS / MANDATORY', '同一个连接,加入外层事务'], ['REQUIRES_NEW', '新事务,新连接 13'], ['NOT_SUPPORTED', '挂起外层事务,无事务,新连接 13'], ['NEVER', '有事务就抛 IllegalTransactionStateException']], ['NEVER'])),
    step("外面有事务、inner 成功之后 outer 抛异常回滚,表里还剩什么。REQUIRED、NESTED、SUPPORTS、MANDATORY:空(inner 的行跟着 outer 一起回滚)。REQUIRES_NEW:剩下 inner(inner 的事务已经独立提交了)。NOT_SUPPORTED:也剩下 inner(inner 根本不在事务里,自动提交)。NEVER:在 inner 处就抛异常了。", t=tl(S(2)), mark=lidx(S(2), 'REQUIRES_NEW   外有事务、inner 成功后', 'NOT_SUPPORTED  外有事务、inner 成功后'), done=lidx(S(2), 'REQUIRED       外有事务、inner 成功后', 'NESTED         外有事务、inner 成功后', 'SUPPORTS       外有事务、inner 成功后', 'MANDATORY      外有事务、inner 成功后'), b=bars([['outer 回滚后 inner 的行一起回滚的个数', 4, '4:REQUIRED、NESTED、SUPPORTS、MANDATORY'], ['outer 回滚后 inner 的行仍在的个数', 2, '2:REQUIRES_NEW、NOT_SUPPORTED']], 4, done=[0], mark=[1]), kv=KV([['inner 加入外层事务', '一起回滚'], ['REQUIRES_NEW', 'inner 已独立提交,留下 inner'], ['NOT_SUPPORTED', 'inner 自动提交,留下 inner'], ['含义', '独立提交的子操作不会被外层回滚撤销']], ['含义'])),
    step("外面有事务、inner 抛异常、outer 把它捕获后继续并正常返回。REQUIRED、SUPPORTS、MANDATORY:outer 结束提交时抛 UnexpectedRollbackException:Transaction rolled back because it has been marked as rollback-only,表里是空——inner 的异常把整个事务标成了 rollback-only,outer 吞掉异常也没用。REQUIRES_NEW:outer 正常结束,剩下 outer(inner 自己的事务回滚了)。NESTED:outer 正常结束,剩下 outer(回滚到 savepoint)。NOT_SUPPORTED:剩下 outer+inner(inner 不在事务里,已经自动提交)。NEVER:在 inner 处抛 IllegalTransactionStateException 被 outer 捕获,剩下 outer。", t=tl(S(3)), mark=lidx(S(3), 'REQUIRED       外有事务、inner 抛异常被 outer 捕获', 'SUPPORTS       外有事务、inner 抛异常被 outer 捕获', 'MANDATORY      外有事务、inner 抛异常被 outer 捕获'), done=lidx(S(3), 'REQUIRES_NEW   外有事务、inner 抛异常被 outer 捕获', 'NESTED         外有事务、inner 抛异常被 outer 捕获', 'NOT_SUPPORTED  外有事务、inner 抛异常被 outer 捕获'), b=bars([['outer 结束时抛 UnexpectedRollbackException 的个数', 3, '3:REQUIRED、SUPPORTS、MANDATORY'], ['outer 正常提交并保留 outer 行的个数', 3, '3:REQUIRES_NEW、NESTED、NEVER'], ['outer 提交且 inner 行也在的个数', 1, '1:NOT_SUPPORTED']], 3, mark=[0], done=[1], cur=[2]), kv=KV([['加入外层事务的', 'inner 异常使整个事务 rollback-only'], ['outer 吞掉异常', '提交时抛 UnexpectedRollbackException'], ['REQUIRES_NEW / NESTED', '只回滚 inner 自己,outer 照常提交'], ['NESTED', '回滚到 savepoint']], ['outer 吞掉异常'])),
    step("外面没有事务时调用 inner 的各种传播行为。REQUIRED、REQUIRES_NEW、NESTED:各自新开一个事务(inner 事务活跃=true)。SUPPORTS、NOT_SUPPORTED、NEVER:在没有事务的状态下执行(事务活跃=false)。MANDATORY:抛 IllegalTransactionStateException:No existing transaction found for transaction marked with propagation 'mandatory'。outer 那一行是在事务外插入的(自动提交),所以其它情形最后行都是 outer+inner。", t=tl(S(4)), mark=lidx(S(4), 'MANDATORY      外面没有事务'), done=lidx(S(4), 'REQUIRED       外面没有事务', 'REQUIRES_NEW   外面没有事务', 'NESTED         外面没有事务', 'SUPPORTS       外面没有事务', 'NOT_SUPPORTED  外面没有事务', 'NEVER          外面没有事务'), b=bars([['新开事务的个数', 3, '3:REQUIRED、REQUIRES_NEW、NESTED'], ['无事务执行的个数', 3, '3:SUPPORTS、NOT_SUPPORTED、NEVER'], ['抛异常的个数', 1, '1:MANDATORY']], 3, done=[0, 1], mark=[2]), kv=KV([['REQUIRED / REQUIRES_NEW / NESTED', '新开事务'], ['SUPPORTS / NOT_SUPPORTED / NEVER', '无事务执行'], ['MANDATORY', '抛 IllegalTransactionStateException'], ['outer 的行', '事务外自动提交']], ['MANDATORY'])),
]
A = mkartx('x30', 30, 'Spring,事务,传播行为,REQUIRES_NEW,NESTED,真实验证,动画演示',
    '实测事务传播行为 7 种:外面有事务时 REQUIRED、NESTED、SUPPORTS、MANDATORY 加入同一个连接,REQUIRES_NEW 与 NOT_SUPPORTED 用另一个连接,NEVER 抛异常;外层回滚时 REQUIRES_NEW 与 NOT_SUPPORTED 的行保留;inner 抛异常被外层吞掉时 REQUIRED 在提交时抛 UnexpectedRollbackException,REQUIRES_NEW 与 NESTED 只回滚自己;外面没有事务时 MANDATORY 抛异常。',
    'REQUIRED、REQUIRES_NEW、NESTED 到底有什么区别?外层回滚了里层还在吗?里层抛异常被外层吞掉会怎样?外面没有事务时每种传播行为是什么表现?这篇用 7 种传播行为乘 4 种场景,在 Spring Framework 7.0.9 和 MySQL 26.7.0 上逐个跑出来。',
    [('3 个', '外层吞掉里层异常时,提交阶段抛 UnexpectedRollbackException 的传播行为个数(REQUIRED、SUPPORTS、MANDATORY)'), ('2 个', '外层回滚后里层的行仍保留的传播行为个数(REQUIRES_NEW、NOT_SUPPORTED)'), ('13 对 12', 'REQUIRES_NEW 内层连接 id 与外层连接 id(另开了连接)')],
    [('外面有事务,都成功', '<p>四种加入同一个连接,REQUIRES_NEW 与 NOT_SUPPORTED 用另一个连接,NEVER 抛异常。</p>'),
     ('外层回滚', '<p>加入外层事务的跟着回滚,独立事务或无事务的内层行留下。</p>'),
     ('里层失败外层捕获', '<p>加入外层事务的会让外层提交时抛 UnexpectedRollbackException;REQUIRES_NEW 与 NESTED 只回滚自己。</p>'),
     ('外面没有事务', '<p>REQUIRED、REQUIRES_NEW、NESTED 新开事务,SUPPORTS、NOT_SUPPORTED、NEVER 无事务执行,MANDATORY 抛异常。</p>')],
    steps,
    [ENV_X + '。用不带 Boot 的 Spring Framework 7.0.9 的 @EnableTransactionManagement + DataSourceTransactionManager + HikariCP + 自己起的 MySQL 26.7.0(innodb);内层方法通过另一个 Bean(Inner)被外层调用,走代理;开发时我曾把分发代码写在 Inner 自己里面,所有传播行为的结果完全相同——那是自调用(见自调用篇),这篇的结果是改成跨 Bean 调用之后跑的',
     '没有验证:NESTED 在不支持 savepoint 的数据库或 JTA 下的行为;读 outer 已写入但未提交的数据时 REQUIRES_NEW 是否会死锁(两个连接争同一行);rollbackFor 对内层异常类型的影响(见下一篇);传播行为与隔离级别的组合;事务超时在内外层的传递'],
    '事务传播行为')
